{
  "name": "@aundal/opencode-token-monsters",
  "version": "0.1.5",
  "description": "OpenCode plugin that shows Token Monsters token usage breakdowns in the TUI sidebar.",
  "author": "aundal",
  "license": "MIT",
  "type": "module",
  "main": "dist/server.js",
  "types": "dist/server.d.ts",
  "exports": {
    ".": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js",
      "default": "./dist/server.js"
    },
    "./server": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js",
      "default": "./dist/server.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js",
      "default": "./dist/tui.js"
    }
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/aundal/opencode-token-monsters.git"
  },
  "homepage": "https://github.com/aundal/opencode-token-monsters#readme",
  "bugs": {
    "url": "https://github.com/aundal/opencode-token-monsters/issues"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "node -e \"require('fs').rmSync('dist',{recursive:true,force:true})\" && bun build src/server.ts src/tui.tsx --outdir dist --target bun --external @opencode-ai/plugin --external @opentui/solid --external solid-js --external gpt-tokenizer && tsc --emitDeclarationOnly",
    "prepack": "bun run build",
    "prepublishOnly": "bun run build",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "token-usage",
    "tokens",
    "tui"
  ],
  "dependencies": {
    "@opentui/solid": "0.4.0",
    "gpt-tokenizer": "^3.4.0",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.4.7",
    "bun-types": "^1.2.19",
    "@types/node": "^24.0.7",
    "typescript": "^5.8.3"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.4.0"
  }
}
